-- 演示数据：可重复执行（先清理带【演示】标记的数据，再重新生成）
SET NAMES utf8mb4;
USE yoloai;

-- 清理旧演示数据
DELETE FROM message WHERE title LIKE '【演示】%';
DELETE FROM work_order WHERE order_no LIKE 'WO-DEMO-%';
DELETE FROM imgrecords WHERE suggestion LIKE '【演示数据】%';
DELETE FROM videorecords WHERE username LIKE 'demo\_%';
DELETE FROM user WHERE username LIKE 'demo\_%' OR email LIKE '%@example.com';

-- 演示用户（密码统一 123456，仅用于本地演示）

-- 检测记录 360 条，分布在最近 60 天

-- 工单 96 张，关联演示检测记录
UPDATE work_order SET record_id = (SELECT id FROM imgrecords WHERE suggestion LIKE '【演示数据】%' ORDER BY RAND() LIMIT 1) WHERE order_no LIKE 'WO-DEMO-%';

-- 消息 180 条
UPDATE message SET work_order_id = (SELECT id FROM work_order WHERE order_no LIKE 'WO-DEMO-%' ORDER BY RAND() LIMIT 1) WHERE title LIKE '【演示】%';

